  "story_comment_id" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  CONSTRAINT "content_mentions_recipient_id_users_id_fk" FOREIGN KEY ("recipient_id") REFERENCES "users" ("id"),
  CONSTRAINT "content_mentions_actor_id_users_id_fk" FOREIGN KEY ("actor_id") REFERENCES "users" ("id"),
  CONSTRAINT "content_mentions_post_id_posts_id_fk" FOREIGN KEY ("post_id") REFERENCES "posts" ("id"),
  CONSTRAINT "content_mentions_story_id_stories_id_fk" FOREIGN KEY ("story_id") REFERENCES "stories" ("id"),
  CONSTRAINT "content_mentions_post_comment_id_post_comments_id_fk" FOREIGN KEY ("post_comment_id") REFERENCES "post_comments" ("id"),
  CONSTRAINT "content_mentions_story_comment_id_story_comments_id_fk" FOREIGN KEY ("story_comment_id") REFERENCES "story_comments" ("id"),
  CONSTRAINT "content_mentions_kind_check" CHECK ("kind" IN ('post', 'post-comment', 'story-comment')),
  CONSTRAINT "content_mentions_not_self_check" CHECK ("recipient_id" <> "actor_id"),
  CONSTRAINT "content_mentions_target_check" CHECK (
    ("kind" = 'post' AND "post_id" IS NOT NULL AND "story_id" IS NULL AND "post_comment_id" IS NULL AND "story_comment_id" IS NULL)
    OR ("kind" = 'post-comment' AND "post_id" IS NOT NULL AND "story_id" IS NULL AND "post_comment_id" IS NOT NULL AND "story_comment_id" IS NULL)
    OR ("kind" = 'story-comment' AND "post_id" IS NULL AND "story_id" IS NOT NULL AND "post_comment_id" IS NULL AND "story_comment_id" IS NOT NULL)
  )
);

