  CONSTRAINT "posts_sports_workout_id_sports_workouts_id_fk" FOREIGN KEY ("sports_workout_id") REFERENCES "sports_workouts" ("id"),
  CONSTRAINT "posts_destination_check" CHECK ("destination" IN ('main', 'community', 'both'))
